var sqlParamter = [];
var invoiceQuery = false;
var billsQuery = false;
var index = 0;

for(var i =0; i<tw.local.searchCriteriaSearchBy.listLength;i++){
if(tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.CIF){
	if( searchBy == "")
 searchBy = "CIF = ?";
 else
 searchBy += " AND CIF = ?";
 sqlParamter[index++] = tw.local.searchCriteria.CIF;
 
}
else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.RequestType){

	if( searchBy == "")
 	 searchBy = "REQUESTTYPE = ?";
 else
 		 searchBy += " AND REQUESTTYPE = ?";
 sqlParamter[index++] = tw.local.searchCriteria.requestType;
 
 
}
else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.BPMRequestNumber){
 if( searchBy == "")
 	 searchBy = "requestNo LIKE ?";
 else
 	searchBy += " AND requestNo LIKE ?";
 sqlParamter[index++] = tw.local.searchCriteria.BPMRequestNo;
 
}
else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.RequestStatus){
	 if( searchBy == "")
 	searchBy = "REQUESTSTATUS = ?";
 else
 	searchBy += " AND REQUESTSTATUS = ?";
 sqlParamter[index++] = tw.local.searchCriteria.requestStatus;
 
}
else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.RequestDate){
 if( searchBy == "")
 	 searchBy = "REQUESTDATE = ?";
 else
 	searchBy += " AND REQUESTDATE = ?";
 sqlParamter[index++] = tw.local.searchCriteria.requestDate;
 
}
else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.InvoiceNumber)	{
	 if( searchBy == "")
 		 searchBy = "INVOICENO = ?";
 	else
 		 searchBy += " AND INVOICENO = ?";
 sqlParamter[index++] = tw.local.searchCriteria.invoiceNo;
 invoiceQuery = true;
 
 
}
else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.BillOfLading){
 	if( searchBy == "")
 	 searchBy = "BILLOFLADINGREF = ?";
 else
 	searchBy += " AND BILLOFLADINGREF = ?";
 sqlParamter[index++] = tw.local.searchCriteria.billOfLading;
 billsQuery = true;
 
}
else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.TradeFoReferenceNumber){
	if( searchBy == "")
 	 searchBy = "FINANCEAPPROVALNO = ?";
 else
 	searchBy += " AND FINANCEAPPROVALNO = ?";
 sqlParamter[index++] = tw.local.searchCriteria.tradeFoRefrenceNo;
 
}
else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.InstanceNumber){
	if( searchBy == "")
 	 searchBy = "BPMINSTANCENUMBER = ?";
 else
 	searchBy += " AND BPMINSTANCENUMBER = ?";
 sqlParamter[index++] = tw.local.searchCriteria.instanceNumber;
 
}
else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.paymentTerms){
	if( searchBy == "")
 	 searchBy = "PAYMENTTERMS = ?";
 else
 	searchBy += " AND PAYMENTTERMS = ?";
 sqlParamter[index++] = tw.local.searchCriteria.paymentTerms;
 
}

else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.Currency){
	if( searchBy == "")
 	 searchBy = "REQUESTCURRENCY = ?";
 else
 	searchBy += " AND REQUESTCURRENCY = ?";
 sqlParamter[index++] = tw.local.searchCriteria.currency;
 
}

else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.Date){
	if( searchBy == "")
 	 searchBy = "REQUESTDATE BETWEEN ? AND ?";
 else
 	searchBy += " AND REQUESTDATE BETWEEN ? AND ?";
 sqlParamter[index++] = tw.local.searchCriteria.dateFrom;
 sqlParamter[index++] = tw.local.searchCriteria.dateTo;
}

else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.DocumentAmount){
	if( searchBy == "")
 	 searchBy = "DOCUMENTAMOUNT BETWEEN ? AND ?";
 else
 	searchBy += " AND DOCUMENTAMOUNT BETWEEN ? AND ?";
 sqlParamter[index++] = tw.local.searchCriteria.documentAmountFrom;
 sqlParamter[index++] = tw.local.searchCriteria.documentAmountTo;
}

else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.CollectableAmount){
	if( searchBy == "")
 	 searchBy = "COLLECTABLEAMOUNT BETWEEN ? AND ?";
 else
 	searchBy += " AND COLLECTABLEAMOUNT BETWEEN ? AND ?";
 sqlParamter[index++] = tw.local.searchCriteria.collectableAmountFrom;
 sqlParamter[index++] = tw.local.searchCriteria.collectableAmountTo;
}

else if (tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.OutstandingAmount){
	if( searchBy == "")
 	 searchBy = "OUTSTANDINGAMOUNT BETWEEN ? AND ?";
 else
 	searchBy += " AND OUTSTANDINGAMOUNT BETWEEN ? AND ?";
 sqlParamter[index++] = tw.local.searchCriteria.outstandingAmountFrom;
 sqlParamter[index++] = tw.local.searchCriteria.outstandingAmountTo;
}
else{}
}
if( invoiceQuery == true){
 tw.local.sql = "select CIF, CUSTOMERNAME, REQUESTTYPE,REQUESTNO ,REQUESTSTATUS ,substatus , REQUESTDATE , currentStepName , BPMInstanceNumber from "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO "
 +"join "+ tw.env.LKP_DB_Schema +".ODC_INVOICE on "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO.ID = "+ tw.env.LKP_DB_Schema +".ODC_INVOICE.REQUESRID " 
 + "where "+searchBy+" AND BPMInstanceNumber <> '' ORDER BY REQUESTNO ASC;"; 
}
else if(billsQuery == true ){
 tw.local.sql = "select CIF, CUSTOMERNAME, REQUESTTYPE,REQUESTNO ,REQUESTSTATUS ,substatus , REQUESTDATE , currentStepName , BPMInstanceNumber from "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO "
 + "join "+ tw.env.LKP_DB_Schema +".ODC_BILLS on "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO.ID = "+ tw.env.LKP_DB_Schema +".ODC_BILLS.REQUESRID " 
 + "where "+searchBy+" AND BPMInstanceNumber <> '' ORDER BY REQUESTNO ASC;"; 
} 
else{
 tw.local.sql = "select CIF, CUSTOMERNAME, REQUESTTYPE,REQUESTNO ,REQUESTSTATUS ,substatus , REQUESTDATE , currentStepName , BPMInstanceNumber from "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO "
 + "where "+searchBy+" AND BPMInstanceNumber <> '' ORDER BY REQUESTNO ASC;"

}

index = 0;

tw.local.sqlParameters = new tw.object.listOf.SQLParameter();
for(var i=0; i<sqlParamter.length;i++){
	tw.local.sqlParameters[i] = new tw.object.SQLParameter();
	tw.local.sqlParameters[i].value = sqlParamter[index++];
}

"]}},{"startQuantity":1,"outgoing":["272ce217-31fa-49a5-8945-b61fd0b017f0"],"incoming":["9d817e86-3fa0-4fa6-8a4c-99f02bd83a9c"],"extensionElements":{"nodeVisualInfo":[{"color":"#FFC875","width":95,"x":846,"y":145,"declaredType":"TNodeVisualInfo","height":70}]},"name":"Set Current Activity name","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"9b65ed8f-1b8c-49fd-88b6-b030f3824ce1","scriptFormat":"text/x-javascript","script":{"content":["for (var i=0; i<tw.local.searchResult.listLength; i++) {
	tw.local.nameList = [];
	var instance;
 	var valid = true;
	var id = tw.local.searchResult[i].bpmInstanceID+"";
//	var activityName = 
//	tw.local.searchResult[i].currentActivityName = "NA";
//	activityName = "NA";
//	var status = tw.local.searchResult[i].requestStatus;
	
	try {
		instance = tw.system.findProcessInstanceByID(id);
	} catch (err) {
		log.info("Instance "+id+" not found");
 	valid = false;
	}

	if (instance != null && instance != undefined && valid == true) {
		for (var j=0; j<tw.system.findProcessInstanceByID(id).tasks.length; j++) {
			if (tw.system.findProcessInstanceByID(id).tasks[j].status == "Received") {
				tw.local.nameList.insertIntoList(tw.local.nameList.listLength, tw.system.findProcessInstanceByID(id).tasks[j].subject);
			}
		}
		tw.local.searchResult[i].currentActivityName = listIntoString();
	}
	
//	if (tw.local.searchResult[i].currentActivityName == "NA" || tw.local.searchResult[i].currentActivityName == "" || tw.local.searchResult[i].currentActivityName == null) {
		if ((tw.local.searchResult[i].requestStatus == "Completed" || tw.local.searchResult[i].requestStatus == "Terminated") && (tw.local.searchResult[i].requestSubstatus == "Completed" || tw.local.searchResult[i].requestSubstatus == "Terminated")) {
			tw.local.searchResult[i].currentActivityName = tw.local.searchResult[i].requestStatus
		}
//		else{
//			activityName = "N/A"
//		}
//	}
};

function listIntoString() {
 var formattedString = '';
 for (var k=0;k<tw.local.nameList.listLength;k++) {
 formattedString += ""+tw.local.nameList[k] + '\n';
 }
 return formattedString;
